import { FINELI_PORTION_UNITS } from "@hovimestari/types";
import { sql } from "drizzle-orm";
import {
  check,
  index,
  integer,
  numeric,
  pgEnum,
  pgTable,
  primaryKey,
  text,
  timestamp,
  uniqueIndex,
  uuid,
} from "drizzle-orm/pg-core";
import { users } from "./users.js";

export const foodSource = pgEnum("food_source", ["fineli", "open_food_facts", "user"]);

/**
 * Every food, whatever its source. A user's own food has an owner, a shared
 * food (Fineli, Open Food Facts) has none. The `search_*` columns are
 * generated by the SQL functions of migration 0001, so the index, the filter
 * and the ranking normalise names one way.
 */
export const foods = pgTable(
  "foods",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    source: foodSource("source").notNull(),
    // The owner of a user's own food. Null on a shared food (Fineli, Open Food Facts).
    userId: uuid("user_id").references(() => users.id, { onDelete: "cascade" }),
    // Fineli's FOODID. The import's join key. The app's identity is `id`, which never changes.
    fineliId: integer("fineli_id").unique(),
    // The Finnish name for a Fineli food, the user's own name for their food.
    name: text("name").notNull(),
    // The English name, where the source has one. Null on a user's own food.
    nameEn: text("name_en"),
    energyKcal: numeric("energy_kcal", { precision: 6, scale: 2, mode: "number" }).notNull(),
    proteinG: numeric("protein_g", { precision: 6, scale: 3, mode: "number" }).notNull(),
    carbsG: numeric("carbs_g", { precision: 6, scale: 3, mode: "number" }).notNull(),
    fatG: numeric("fat_g", { precision: 6, scale: 3, mode: "number" }).notNull(),
    barcode: text("barcode"),
    // Fineli's FOODTYPE (FOOD or DISH) and PROCESS code (RAW, BOIL, ...). Null elsewhere.
    fineliType: text("fineli_type"),
    fineliProcess: text("fineli_process"),
    // Set when a Fineli food is absent from the latest release. Hidden from search, still readable.
    retiredAt: timestamp("retired_at", { withTimezone: true }),
    // Deleted by its owner while entries use it. Every food read leaves it out (visibleTo).
    deletedAt: timestamp("deleted_at", { withTimezone: true }),
    searchName: text("search_name").generatedAlwaysAs(sql`food_search_norm(name)`),
    searchNameEn: text("search_name_en").generatedAlwaysAs(sql`coalesce(food_search_norm(name_en), '')`),
    searchAll: text("search_all").generatedAlwaysAs(sql`food_search_norm(name || ' ' || coalesce(name_en, ''))`),
    // The first word of the first part, hyphens kept, for the ranking's head tiers.
    searchHead: text("search_head").generatedAlwaysAs(sql`food_search_head(name)`),
    searchHeadEn: text("search_head_en").generatedAlwaysAs(sql`coalesce(food_search_head(name_en), '')`),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
    updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    check("foods_owner_matches_source", sql`(${t.source} = 'user') = (${t.userId} IS NOT NULL)`),
    check("foods_fineli_id_matches_source", sql`(${t.source} = 'fineli') = (${t.fineliId} IS NOT NULL)`),
    check(
      "foods_values_in_range",
      sql`${t.energyKcal} BETWEEN 0 AND 1000 AND ${t.proteinG} BETWEEN 0 AND 100 AND ${t.carbsG} BETWEEN 0 AND 100 AND ${t.fatG} BETWEEN 0 AND 100`,
    ),
    check("foods_barcode_digits", sql`${t.barcode} ~ '^[0-9]{8,14}$'`),
    uniqueIndex("foods_user_barcode_uq")
      .on(t.userId, t.barcode)
      .where(sql`${t.source} = 'user' AND ${t.barcode} IS NOT NULL`),
    index("foods_user_id_idx").on(t.userId),
    index("foods_search_all_trgm").using("gin", t.searchAll.op("gin_trgm_ops")),
  ],
);

/**
 * Ways to enter grams for a food. A Fineli portion has a unit code, no owner
 * and no name. A user's portion has a name and an owner, and only that user sees it.
 */
export const foodPortions = pgTable(
  "food_portions",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    foodId: uuid("food_id")
      .notNull()
      .references(() => foods.id, { onDelete: "cascade" }),
    // The user who added it. Null on a portion that comes with the food's source.
    userId: uuid("user_id").references(() => users.id, { onDelete: "cascade" }),
    // Fineli's FOODUNIT code (KPL_M, DL, ...). The web renders its label from the catalog.
    fineliUnit: text("fineli_unit"),
    // A user's own label, such as "one tub".
    name: text("name"),
    grams: numeric("grams", { precision: 6, scale: 1, mode: "number" }).notNull(),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
    updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    check("food_portions_one_label", sql`(${t.fineliUnit} IS NULL) <> (${t.name} IS NULL)`),
    // Only the units the API names, so a reader can trust the code it casts.
    check(
      "food_portions_fineli_unit_known",
      sql`${t.fineliUnit} IN (${sql.raw(FINELI_PORTION_UNITS.map((u) => `'${u}'`).join(", "))})`,
    ),
    check("food_portions_fineli_unowned", sql`${t.fineliUnit} IS NULL OR ${t.userId} IS NULL`),
    check("food_portions_grams_positive", sql`${t.grams} > 0 AND ${t.grams} <= 5000`),
    uniqueIndex("food_portions_fineli_unit_uq")
      .on(t.foodId, t.fineliUnit)
      .where(sql`${t.fineliUnit} IS NOT NULL`),
    index("food_portions_food_id_idx").on(t.foodId),
    index("food_portions_user_id_idx").on(t.userId),
  ],
);

/** A user's favourite foods. */
export const foodFavourites = pgTable(
  "food_favourites",
  {
    userId: uuid("user_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    foodId: uuid("food_id")
      .notNull()
      .references(() => foods.id, { onDelete: "cascade" }),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [primaryKey({ columns: [t.userId, t.foodId] }), index("food_favourites_food_id_idx").on(t.foodId)],
);
